def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v == 0]
        if len(marks) > 1:
            for c in range(min(marks), max(marks) + 1):
                if out[r][c] == 9:
                    out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == 0]
        if len(marks) > 1:
            for r in range(min(marks), max(marks) + 1):
                if out[r][c] == 9:
                    out[r][c] = 3
    return out
